/bin/bash -lc "node --input-type=module <<'NODE'
const cases = [
  ['/products/lamp?currency=EUR', ['Brass lamp', 'EUR 110.40', 'Stone vase']],
  ['/products/lamp?currency=USD', ['Brass lamp', 'USD 120.00', 'Stone vase']],
  ['/products/vase?currency=EUR', ['Stone vase', 'EUR 73.60', 'Brass lamp']],
  ['/products/lamp', ['Brass lamp', 'USD 120.00', 'Stone vase']],
]
for (const [path, expected] of cases) {
  const start = performance.now()
  const response = await fetch("'`http://localhost:3100${path}`)
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let html = '"''
  const chunks = []
  while (true) {
    const { value, done } = await reader.read()
    if (done) break
    const chunk = decoder.decode(value, { stream: true })
    chunks.push({ ms: Math.round(performance.now() - start), bytes: value.length, shopFrame: chunk.includes('Signal Shop collection'), product: chunk.includes(expected[1]), related: chunk.includes('Related products') })
