  }
  const missing = expected.filter((text) => "'!html.includes(text))
  console.log(JSON.stringify({ path, status: response.status, expectedPresent: missing.length === 0, missing, chunks }))
  if (response.status !== 200 || missing.length) process.exitCode = 1
}
